TLM.f("Sancti/03-12",{"officium":"S. Gregorii Papæ Confessoris et Ecclesiæ Doctoris","rule":["vide C4b;","Gloria","CredoDA"],"ruleInherited":["Prefatio=Apostolis"],"fallback":"Commune/C4b","from":{"Introitus":"Commune/C4b","Lectio":"Commune/C4b","Graduale":"Commune/C4b","GradualeP":"Commune/C4b","Tractus":"Commune/C4b","Evangelium":"Commune/C4b","Offertorium":"Commune/C4b","Communio":"Commune/C4b"},"sections":{"Introitus":[{"k":"ref","la":"Joann 21:15-17"},{"k":"text","la":"Si díligis me, Simon Petre, pasce agnos meos, pasce oves meas. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 29:2"},{"k":"text","la":"Exaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Si díligis me, Simon Petre, pasce agnos meos, pasce oves meas. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui ánimæ fámuli tui Gregórii ætérnæ beatitúdinis prǽmia contulísti: concéde propítius; ut, qui peccatórum nostrórum póndere prémimur, ejus apud te précibus sublevémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet 5:1-4; 5:10-11"},{"k":"text","la":"Caríssimi: Senióres, qui in vobis sunt, obsécro consénior et testis Christi passiónum, qui et ejus, quæ in futúro revelánda est, glóriæ communicátor: páscite qui in vobis est gregem Dei, providéntes non coácte, sed spontánee secúndum Deum, neque turpis lucri grátia, sed voluntárie; neque ut dominántes in cleris, sed forma facti gregis ex ánimo. Et, cum apparúerit princeps pastórum, percipiétis immarcescíbilem glóriæ corónam. Deus autem omnis grátiæ, qui vocávit nos in ætérnam suam glóriam in Christo Jesu, módicum passos ipse perfíciet, confirmábit solidabítque. Ipsi glória et impérium in sǽcula sæculórum. Amen."}],"Graduale":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."},{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in Ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus; et mirabília ejus fíliis hóminum","mark":"V"},{"k":"ref","la":"Ps 39:10-11"},{"k":"text","la":"Annuntiávi justítiam tuam in ecclésia magna, ecce, lábia mea non prohibébo: Dómine, tu scisti."},{"k":"text","la":"Justítiam tuam non abscóndi in corde meo: veritátem tuam et salutáre tuum dixi.","mark":"V"},{"k":"text","la":"Non abscóndi misericórdiam tuam, et veritátem tuam a concílio multo.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:13-19"},{"k":"text","la":"In illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis."}],"Offertorium":[{"k":"ref","la":"Jer 1:9-10"},{"k":"text","la":"Ecce, dedi verba mea in ore tuo: ecce, constítui te super gentes et super regna, ut evéllas et déstruas, et ædífices et plantes. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Annue nobis, quǽsumus, Dómine: ut intercessióne beáti Gregórii hæc nobis prosit oblátio, quam immolándo totíus mundi tribuísti relaxári delícta."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Deus, qui beátum Gregórium Pontíficem Sanctórum tuórum méritis coæquásti: concéde propítius; ut, qui commemoratiónis ejus festa percólimus, vitæ quoque imitémur exémpla."},{"k":"macro","name":"Per Dominum"}]},"hr":{"9fb2c37be70c5a42":{"t":"<i>Pomolimo se</i>.\nBože koji si duši sluge tvoga Grgura dao nagradu vječnog blaženstva, podaj milostivo da se mi, koji smo pritisnuti težinom naših grijeha, prošnjama uzdignemo k tebi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B. po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]","kn":"Bože, koji si duši sluge svoga Grgura udijelio nagradu vječnoga blaženstva, dopusti milostivo, da nas. koje pritište težina naših grijeha, pridignu njegove molitve do Tebe, po G. n.","knRef":"Kniewald 1942, str. 522–523 (snimka 262) (OCR)"},"bb4cdd35a4d634c9":{"t":"Udijeli, molimo, Gospodine, da zagovorom blaženog Grgura bude na dobrobit ovaj prinos, po čijem si žrtvovanju htio da cijeli svijet postigne oproštenje grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B. po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]","kn":"Molimo Te, Gospodine, obazri se na nas i podaj, da nam zagovorom blaženoga Grgura uskoristi ovaj prinos, kojega si žrtvovanjem htio da se otpuste grijesi cijeloga svijeta, po G. n.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"},"2a540c6e4e077c89":{"t":"<i>Pomolimo se</i>.\nBože koji si blaženog Grgura biskupa u zaslugama izjednačio sa svojim svecima, podaj milostivo da mi, koji spominjući se slavimo njegov blagdan, također slijedimo primjer njegovog života.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B. po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]","kn":". Bože, koji si blaženoga Grgura zaslugama izjednačio sa svojim svetima, dopusti milostivo, da svetkujući njegov spomendan nasljedujemo primjer njegova života, po G. n.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."},{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine. Allelúja."}]}}});
